import { mapFallbackLocation } from './observatorio-news-geo.mjs';
// Carga bajo demanda: las noticias y sus acciones no esperan a las fotos.
export function createNewsPhotos(){
 const cache=new Map(),pending=new Set(),queue=[];let active=0,observer;const maps=new Map(),queries=new Map();
 const query=id=>queries.get(id)?'&q='+encodeURIComponent(queries.get(id)):'';
 function fallback(id){for(const card of document.querySelectorAll(`[data-photo-id="${id}"]`)){const art=card.querySelector('.story-art'),place=mapFallbackLocation(card.dataset.headline);if(!art||art.classList.contains('has-photo')||maps.has(art)||!place||!window.L)continue;art.hidden=false;art.classList.add('has-map');card.classList.add('has-media');const canvas=document.createElement('div');canvas.className='story-location-map';canvas.setAttribute('role','img');canvas.setAttribute('aria-label',`Mapa de referencia: ${place.label}. Ubicación aproximada, no confirmada.`);const caption=document.createElement('div');caption.className='map-caption';caption.textContent=`${place.label} · referencia aproximada`;art.append(canvas,caption);const map=L.map(canvas,{zoomControl:false,scrollWheelZoom:false,dragging:false,touchZoom:false,doubleClickZoom:false,boxZoom:false,keyboard:false}).setView([place.coordinates[1],place.coordinates[0]],4);maps.set(art,map);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap'}).addTo(map).on('tileerror',()=>{if(!maps.has(art))return;map.remove();maps.delete(art);art.replaceChildren();art.hidden=true;card.classList.remove('has-media');});L.circleMarker([place.coordinates[1],place.coordinates[0]],{radius:7,color:'#fff',weight:2,fillColor:'#12634f',fillOpacity:1}).addTo(map);requestAnimationFrame(()=>map.invalidateSize());}}
 function state(id,value){document.querySelectorAll(`[data-photo-id="${id}"]`).forEach(c=>c.dataset.photoState=value);}
 function apply(id,photo){if(!photo){state(id,'unavailable');fallback(id);return;}state(id,'loading-image');for(const card of document.querySelectorAll(`[data-photo-id="${id}"]`)){
 const art=card.querySelector('.story-art');if(!art||art.querySelector('img'))continue;
 let url;try{url=new URL(photo.url);if(url.protocol!=='https:'){fallback(id);continue;}}catch{fallback(id);continue;}
 const img=document.createElement('img');img.className='source-photo';img.alt=photo.alt||`Imagen publicada por ${photo.source} para esta noticia`;img.referrerPolicy='no-referrer';img.decoding='async';
 const timeout=setTimeout(()=>{state(id,'image-timeout');img.onload=null;img.onerror=null;img.remove();fallback(id);},15000);
 img.onload=()=>{clearTimeout(timeout);if(img.naturalWidth<160||img.naturalHeight<90){img.remove();fallback(id);return;}state(id,'loaded');art.hidden=false;card.classList.add('has-media');if(maps.has(art)){maps.get(art).remove();maps.delete(art);art.querySelector('.map-caption')?.remove();}art.classList.add('has-photo');art.removeAttribute('aria-hidden');const credit=document.createElement('a');credit.className='photo-credit';credit.textContent='Imagen: '+photo.source+' ↗';credit.href=photo.articleUrl;credit.target='_blank';credit.rel='noopener noreferrer';art.append(credit);};
 img.onerror=()=>{clearTimeout(timeout);state(id,'image-error');img.remove();fallback(id);};img.src='/.netlify/functions/news-photo?id='+id+query(id);art.append(img);
 }}
 async function pump(){if(active>=3||!queue.length)return;const id=queue.shift();active++;state(id,'loading-metadata');try{const r=await fetch('/.netlify/functions/news-image?id='+id+query(id),{signal:AbortSignal.timeout(22000)});const photo=r.ok?(await r.json()).image:null;cache.set(id,photo);apply(id,photo);}catch{cache.set(id,null);state(id,'request-error');fallback(id);}finally{active--;pending.delete(id);pump();}}
 function enqueue(id){if(cache.has(id)){apply(id,cache.get(id));return;}if(pending.has(id))return;pending.add(id);queue.push(id);pump();}
 return root=>{root.querySelectorAll('[data-photo-id]').forEach(card=>queries.set(card.dataset.photoId,card.dataset.searchQuery||''));for(const [art,map] of maps){map.remove();}maps.clear();observer?.disconnect();observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){observer.unobserve(e.target);enqueue(e.target.dataset.photoId);}},{rootMargin:'250px'});root.querySelectorAll('[data-photo-id]').forEach((card,index)=>{if(cache.has(card.dataset.photoId))apply(card.dataset.photoId,cache.get(card.dataset.photoId));else if(index<3)enqueue(card.dataset.photoId);else observer.observe(card);});};
}
